import {defaultAppearance,pickAppearance,appearanceKeys} from './appearance.js';
const enums={palette:['sand','cocoa','olive','ink','ivory','custom'],darkPalette:['paired','ink','cocoa','olive','midnight'],uiFont:['alexandria','plex','readex','cairo','tajawal','almarai','system'],readingFont:['naskh','alexandria','readex','plex','cairo','system'],fontWeight:['400','500','600'],density:['compact','comfortable','spacious'],corners:['soft','crisp'],sidebarTone:['light','dark'],sidebarSide:['left','right'],navigationStyle:['labels','icons'],readingWidth:['narrow','comfortable','wide'],readingLineHeight:['1.6','2','2.3','2.6'],readingSize:['18','22','26','30'],paragraphSpacing:['simple','medium','clear'],defaultMode:['quick','normal','deep'],surfaceTreatment:['paper','flat'],appearancePreset:['quiet','book','modern','warm','custom'],theme:['light','dark','system']};
const bools=['showWeek','showOnThisDay','showEmotionHelper','showDailyModes','reduceMotion'];
function valid(k,v){if(Object.hasOwn(enums,k))return (typeof v==='string'||typeof v==='number')&&enums[k].includes(String(v));if(bools.includes(k))return typeof v==='boolean';if(['customAccent','customBackground'].includes(k))return typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v);if(k==='textSize')return typeof v==='number'&&[15,17,19,22,25,28].includes(v);return false}
const normalize=(k,v)=>Object.hasOwn(enums,k)?String(v):v;
export function appearanceProfile(p){const defaults={...defaultAppearance(),theme:'system',textSize:17};const values=pickAppearance(p);return {format:'qadawi-appearance',version:1,createdAt:new Date().toISOString(),preferences:Object.fromEntries(appearanceKeys.map(k=>[k,normalize(k,valid(k,values[k])?values[k]:defaults[k])]))}}
export function validateAppearanceProfile(data){if(!data||typeof data!=='object'||Array.isArray(data)||data.format!=='qadawi-appearance'||data.version!==1)throw new Error('هذا ليس ملف خيارات عرض من قضاوي. استخدم النسخ الاحتياطي لاستعادة الدفتر.');if(Object.keys(data).some(k=>!['format','version','createdAt','preferences'].includes(k)))throw new Error('ملف العرض يحتوي حقولًا غير متوقعة.');const p=data.preferences;if(!p||typeof p!=='object'||Array.isArray(p)||!Object.keys(p).length)throw new Error('ملف العرض فارغ أو غير صالح.');const result={};for(const [k,v]of Object.entries(p)){if(!appearanceKeys.includes(k)||!valid(k,v))throw new Error('خيار عرض غير صالح: '+k);result[k]=normalize(k,v)}return result}
